namespace ghidra.file.formats.gzip;



using ghidra.app.util.bin;
using ghidra.app.util.bin;
using ghidra.program.model.listing;

public class GZipUtil {
	
	public static bool isGZip( Program program ) {
		ByteProvider provider =
			MemoryByteProvider.createDefaultAddressSpaceByteProvider(program, true);
		return isGZip( provider );
	}

	public static bool isGZip( ByteProvider provider ) {
		try {
			byte [] bytes = provider.readBytes( 0, GZipConstants.MAGIC_BYTES.length  );
			return Arrays.equals( bytes, GZipConstants.MAGIC_BYTES );
		}
		catch (Exception e) {
		}
		return false;
	}

	public static bool isGZip( byte [ ] bytes ) {
		if ( bytes.length >= GZipConstants.MAGIC_BYTES.length ) {
			return bytes[ 0 ] == GZipConstants.MAGIC_BYTES[ 0 ] && bytes[ 1 ] == GZipConstants.MAGIC_BYTES[ 1 ];
		}
		return false;
	}
}
